-- 2026-10-27 / AIDP 연결 / SIDDS.*_S 실버, SIDDA.*_A 에이전트
-- 기존 무접미사 LGL/LEGAL 테이블은 보존한다. 데이터 복사·삭제·이름 변경 없음.
-- 각 SQL 문을 별도 Query에서 실행. 이미 존재하는 객체는 건너뛰고 check로 구조 검사.
-- DDL은 자동 커밋. SIDDS/SIDDA 생성 권한이 없으면 해당 스키마 담당자에게 전달.
-- 실행 매핑 SHA256: 05fe79d3324b1a68f8e93c554358eb860b38165bd06d1ce1225e0a06f89e93c9

SELECT SYS_CONTEXT('USERENV','SESSION_USER') AS LOGIN_USER, SYS_CONTEXT('USERENV','DB_UNIQUE_NAME') AS DB_NAME, SYS_CONTEXT('USERENV','CURRENT_SCHEMA') AS CURRENT_SCHEMA_NAME FROM DUAL;

SELECT OWNER,OBJECT_NAME,OBJECT_TYPE FROM ALL_OBJECTS WHERE ((OWNER='SIDDS' AND OBJECT_NAME='LGL_DOC_VER_S') OR (OWNER='SIDDS' AND OBJECT_NAME='LGL_DOC_UNIT_S') OR (OWNER='SIDDS' AND OBJECT_NAME='LGL_DOC_BLK_S') OR (OWNER='SIDDS' AND OBJECT_NAME='LGL_FILE_PART_S') OR (OWNER='SIDDS' AND OBJECT_NAME='LGL_SRC_PBLS_S') OR (OWNER='SIDDS' AND OBJECT_NAME='LGL_SRCH_PBLS_S') OR (OWNER='SIDDS' AND OBJECT_NAME='LGL_SRCH_ROW_S') OR (OWNER='SIDDS' AND OBJECT_NAME='LGL_SRCH_CHNL_S') OR (OWNER='SIDDA' AND OBJECT_NAME='LGL_EXEC_ST_A') OR (OWNER='SIDDS' AND OBJECT_NAME='LGL_SRCH_ROW_KEY_IX_S') OR (OWNER='SIDDS' AND OBJECT_NAME='LGL_SRCH_ROW_OWNR_IX_S') OR (OWNER='SIDDS' AND OBJECT_NAME='LGL_SRCH_ROW_TGT_IX_S') OR (OWNER='SIDDS' AND OBJECT_NAME='LGL_SRCH_ROW_DOC_IX_S')) ORDER BY OWNER,OBJECT_TYPE,OBJECT_NAME;
